// pricing/index.ts: the only door into pricing logic
export function quote(input: QuoteInput): Quote {
  const rules = loadActiveRules(input.region);
  return applyRules(rules, input);
}

// Send migrated modules to the new app; everything else stays on PHP.
const MIGRATED = ["/login", "/students", "/timetable"];

export function upstreamFor(pathname: string) {
  return MIGRATED.some((path) => pathname.startsWith(path)) ? NEW_APP : LEGACY_PHP;
}
